6: // Constants for cyclic rotation.
7: static __m128i crotr8, crotr16;
8: 
9: #ifdef __GNUC__
10: __attribute__((target("sse2")))
11: #endif
12: static void blake2s_init_sse()
13: {
14:   // We cannot initialize these 128 bit variables in place when declaring
15:   // them globally, because global scope initialization is performed before
16:   // our SSE check and it would make code incompatible with older non-SSE2
17:   // CPUs. Also we cannot initialize them as static inside of function
18:   // using these variables, because SSE static initialization is not thread
19:   // safe: first thread starts initialization and sets "init done" flag even
20:   // if it is not done yet, second thread can attempt to access half-init
21:   // SSE data. So we moved init code here.
22: 
23:   blake2s_IV_0_3 = _mm_setr_epi32( 0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A );
24:   blake2s_IV_4_7 = _mm_setr_epi32( 0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19 );
25: 
26:   crotr8 = _mm_set_epi8( 12, 15, 14, 13, 8, 11, 10, 9, 4, 7, 6, 5, 0, 3, 2, 1 );
27:   crotr16 = _mm_set_epi8( 13, 12, 15, 14, 9, 8, 11, 10, 5, 4, 7, 6, 1, 0, 3, 2 );
28: }
