39: #define G1(row1,row2,row3,row4,buf) \
40:   row1 = _mm_add_epi32( _mm_add_epi32( row1, buf), row2 ); \
41:   row4 = _mm_xor_si128( row4, row1 ); \
42:   row4 =  mm_rotr_epi32(row4, 16); \
43:   row3 = _mm_add_epi32( row3, row4 );   \
